-- MW_003 B1 · reference data for the New Request forms (spec B2 "reference lists", B8).
-- Public, read-only lists served by GET /api/reference/:list (cached), never hard-coded in the
-- web app. Written only by migrations; clients read active rows. Generated by a script.
--
-- countries.china_delivery: delivery countries of the "Shipping from SHEIN & Chinese sites" form.
-- cities:   main cities of the delivery countries and of the usual land routes; any other
--           city is entered as "Other" (manual text, stored separately from the list id).
-- ports:    stable internal ids (EG-ALEXANDRIA); `unlocode` only where well known, the
--           others are NULL until checked against the official UN/LOCODE list.
-- airports: IATA code as id. "Any airport" is a flag on the order, not a row.
-- container_types / truck_types / shipping_lines: PLACEHOLDER starter lists (decision 27),
--           to be replaced from the demo's lists. Shipping lines are brand names (same text).
-- transit_estimates: configurable delivery times (spec B5 + decision 28).

alter table public.countries add column china_delivery boolean not null default false;
update public.countries set china_delivery = true
where code in ('EG', 'SA', 'AE', 'KW', 'QA', 'BH', 'OM', 'JO');

create table public.cities (
  id           text primary key check (id ~ '^[A-Z]{2}-[A-Z0-9_]{2,40}$'),
  country_code char(2) not null references public.countries (code),
  name_ar      text not null check (char_length(name_ar) between 2 and 80),
  name_en      text not null check (char_length(name_en) between 2 and 80),
  sort         smallint not null default 100,
  active       boolean not null default true,
  constraint cities_country_prefix_check check (left(id, 2) = country_code),
  constraint cities_country_id_key unique (country_code, id)
);

create table public.ports (
  id           text primary key check (id ~ '^[A-Z]{2}-[A-Z0-9_]{2,40}$'),
  country_code char(2) not null references public.countries (code),
  unlocode     char(5) unique check (unlocode ~ '^[A-Z]{2}[A-Z2-9]{3}$'),
  name_ar      text not null check (char_length(name_ar) between 2 and 100),
  name_en      text not null check (char_length(name_en) between 2 and 100),
  sort         smallint not null default 100,
  active       boolean not null default true,
  constraint ports_country_prefix_check
    check (left(id, 2) = country_code and (unlocode is null or left(unlocode, 2) = country_code)),
  constraint ports_country_id_key unique (country_code, id)
);

create table public.airports (
  id           char(3) primary key check (id ~ '^[A-Z]{3}$'), -- IATA
  country_code char(2) not null references public.countries (code),
  name_ar      text not null check (char_length(name_ar) between 2 and 100),
  name_en      text not null check (char_length(name_en) between 2 and 100),
  sort         smallint not null default 100,
  active       boolean not null default true,
  constraint airports_country_id_key unique (country_code, id)
);

create table public.container_types (
  id      text primary key check (id ~ '^[a-z0-9_]{2,40}$'),
  name_ar text not null check (char_length(name_ar) between 2 and 80),
  name_en text not null check (char_length(name_en) between 2 and 80),
  sort    smallint not null default 100,
  active  boolean not null default true
);

create table public.truck_types (like public.container_types including all);
create table public.shipping_lines (like public.container_types including all);

create table public.transit_estimates (
  source   text not null check (source in ('china_sites', 'shein')),
  method   text not null check (method in ('air', 'sea', 'land')),
  min_days smallint not null check (min_days between 1 and 365),
  max_days smallint not null check (max_days between 1 and 365),
  active   boolean not null default true,
  primary key (source, method),
  constraint transit_estimates_range_check check (min_days <= max_days)
);

comment on table public.cities is 'Reference list (MW_003 B1): main cities per country.';
comment on table public.ports is 'Reference list (MW_003 B1): seaports. unlocode NULL = not verified yet.';
comment on table public.airports is 'Reference list (MW_003 B1): cargo airports, IATA id.';
comment on table public.container_types is 'Reference list (MW_003 B1). PLACEHOLDER until the demo list.';
comment on table public.truck_types is 'Reference list (MW_003 B1). PLACEHOLDER until the demo list.';
comment on table public.shipping_lines is 'Reference list (MW_003 B1). PLACEHOLDER until the demo list.';
comment on table public.transit_estimates is
  'Delivery time per source × method (MW_003 B5), shown to the customer; edit here, not in code.';

-- ── RLS: public read of active rows, no client writes ───────────────────────
do $$
declare
  t text;
begin
  foreach t in array array['cities', 'ports', 'airports', 'container_types', 'truck_types',
                           'shipping_lines', 'transit_estimates'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
    execute format('grant select on table public.%I to anon, authenticated', t);
    execute format(
      'create policy %I on public.%I for select to anon, authenticated using (active)',
      t || ': anyone can read active rows', t
    );
  end loop;
end;
$$;

